/**
 * What the office pays out for an incident reported against a policy.
 *
 * The office settles an incident one damaged item at a time, and the incident's payout is
 * what those settlements come to. The deductible is withheld per damage event, which is why
 * it belongs to the single settlement and not to the tally.
 */
public class PayoutCalculator {

    private static final int DEDUCTIBLE = 100;

    private final ReimbursementClause reimbursementClause = new ReimbursementClause();

    public int payoutFor(Incident incident, InsuredItems insuredItems) {
        double payout = 0;
        for (Damage damage : incident.damages()) {
            payout += settlementFor(damage, insuredItems);
        }
        return OfficesFavour.onAmountPaidOut(payout);
    }

    /**
     * What one damaged item is settled at: the damage the office reimburses under the
     * clauses that cover it, less the deductible it withholds for every damage event.
     */
    private double settlementFor(Damage damage, InsuredItems insuredItems) {
        return reimbursementClause.reimbursedAmountFor(damage, insuredItems.coveringItemFor(damage))
                - DEDUCTIBLE;
    }
}
=== ReimbursementClause.java ===
/**
 * How much of a reported damage the office reimburses, before the deductible.
 *
 * The office reimburses damage in full unless a special clause says otherwise. Damage to a
 * highly enchanted item is reimbursed at half, the magic having borne part of the harm.
 */
public class ReimbursementClause {

    private static final double HALF_REIMBURSEMENT_RATE = 0.50;

    /** The enchantment level from which the office reimburses a damage at half. */
    private static final int HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;

    public double reimbursedAmountFor(Damage damage, Item damagedItem) {
        if (isHighlyEnchanted(damagedItem)) {
            return damage.amount() * HALF_REIMBURSEMENT_RATE;
        }
        return damage.amount();
    }

    private boolean isHighlyEnchanted(Item item) {
        return item.enchantment() >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL;
    }
}
