import java.util.ArrayList;
import java.util.List;

/**
 * Works through a scenario's steps in the order the office received them.
 *
 * The office keeps count of the customer's earlier contracts as it goes, because a quote is
 * assessed against the history that stands before it. Only a quote creates a contract; a claim
 * is made against a policy that already exists and so leaves that history untouched.
 */
public class ClaimOffice {

    private final PremiumCalculator premiumCalculator = new PremiumCalculator();
    private final PayoutCalculator payoutCalculator = new PayoutCalculator();

    public List<StepResult> run(Scenario scenario) {
        List<StepResult> results = new ArrayList<>();
        int earlierContracts = 0;
        for (Step step : scenario.steps()) {
            if (step instanceof QuoteStep quoteStep) {
                results.add(quote(quoteStep, scenario.customer(), earlierContracts));
                earlierContracts++;
            } else {
                results.add(settle((ClaimStep) step, scenario));
            }
        }
        return results;
    }

    private QuoteResult quote(QuoteStep quoteStep, Customer customer, int earlierContracts) {
        QuoteAssessment assessment = new QuoteAssessment(customer, earlierContracts);
        return new QuoteResult(premiumCalculator.premiumFor(quoteStep, assessment));
    }

    private ClaimResult settle(ClaimStep claimStep, Scenario scenario) {
        InsuredItems insuredItems = insuredItemsOf(claimStep, scenario);
        return new ClaimResult(payoutCalculator.payoutFor(claimStep.incident(), insuredItems), 0);
    }

    private InsuredItems insuredItemsOf(ClaimStep claimStep, Scenario scenario) {
        return new InsuredItems(((QuoteStep) scenario.steps().get(claimStep.policy())).items());
    }
}
